/* ----------------------------------------------------
   CARDS COMPONENT (Compact Modern Glass UI - Theme Aware)
---------------------------------------------------- */

import { drillDown } from "./breadcrumb.js";

/* ----------------------------------------------------
   STYLE INJECTION
---------------------------------------------------- */

let stylesInjected = false;

function injectStyles() {

    if (stylesInjected) return;

    const style = document.createElement("style");

    style.innerHTML = `
        .cards {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(22rem, 1fr));
            gap: 1.4rem;
        }

        .card {
            position: relative;
            overflow: hidden;
            padding: 1.4rem;
            border-radius: 1.8rem;
            cursor: pointer;

            color: var(--text-main, #ffffff);
            background: var(--card-bg, rgba(255,255,255,0.10));
            border: 1px solid var(--border, rgba(255,255,255,0.10));
            box-shadow: var(--shadow-sm, 0 2px 8px rgba(0,0,0,0.1));

            transition:
                transform .25s ease,
                box-shadow .25s ease,
                background .25s ease;
        }

        .card:hover {
            transform: translateY(-4px);
            border-left-color: var(--primary, #3182ce);
            border-right-color: var(--primary, #3182ce);
            border-bottom-color: var(--primary, #3182ce);
            box-shadow: 0 12px 28px rgba(0,0,0,0.18);
        }

        // Deaktiviert Effekte auf der Sensor-Endebene
        .card.no-click {
            cursor: default;
        }
        .card.no-click:hover {
            transform: none;
            border-color: var(--border, rgba(255,255,255,0.10));
            box-shadow: 0 8px 24px rgba(0,0,0,0.12);
        }

        .card-header {
            display: flex;
            justify-content: space-between;
            align-items: flex-start;
            margin-bottom: 0.8rem;
        }

        /* Richtet Titel-Text und Punkt bündig nebeneinander aus */
        .card-title {
            display: inline-flex;
            align-items: center;
            gap: 0.6rem;
            font-size: 1.4rem;
            font-weight: 700;
            letter-spacing: 0.02em;
            color: var(--text-main, #ffffff);

            /* ✨ FIX: Erzwingt den Zeiger-Mauszeiger und verhindert Textmarkierung */
            cursor: inherit;
            user-select: none;
            -webkit-user-select: none;
        }

        /* Erzeugt den Punkt virtuell VOR dem Text, ohne JavaScript zu stören */
        .card-title::before {
            content: "";
            width: 8px;
            height: 8px;
            border-radius: 50%;
            margin-right: 0.6rem;
            display: inline-block;
            transition: background-color 0.3s, box-shadow 0.3s;
        }

        /* Zustand: Aktiv -> Grün leuchtend */
        .card[data-active="true"] .card-title::before {
            background-color: #10b981;
            box-shadow: 0 0 8px #10b981;
            position: relative;
        }

        /* Zustand: Inaktiv -> Mattes Grau */
        .card[data-active="false"] .card-title::before {
            background-color: #94a3b8;
            box-shadow: none;
            opacity: 0.5;
        }

        .card-value {
            font-size: 2.1rem;
            font-weight: 800;
            line-height: 1;
            margin-top: 0.35rem;
            color: var(--text-main, #ffffff);
        }

        .card-unit {
            color: var(--text-muted, rgba(255, 255, 255, 0.7));
            font-size: 1rem;
            margin-left: 0.2rem;
        }

        .card-delta {
            font-size: 1.1rem;
            font-weight: 700;
            padding: 0.35rem 0.7rem;
            border-radius: 999px;
            background: rgba(128,128,128,0.08);
        }

        .sparkline-wrapper {
            position: relative;
            height: 60px;
            margin: 1rem -0.3rem 1rem -0.3rem;
        }

        .sparkline {
            width: 100%;
            height: 100%;
            display: block;
        }

        .card-stats {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 0.7rem;
        }

        .stat {
            padding: 0.7rem;
            border-radius: 1rem;
            background: rgba(128,128,128,0.05);
            border: 1px solid var(--border, rgba(255,255,255,0.06));
            text-align: center;
        }

        .stat-label {
            font-size: 1rem;
            color: var(--text-muted, rgba(255,255,255,0.65));
            margin-bottom: 0.25rem;
        }

        .stat-value {
            font-size: 1.2rem;
            font-weight: 700;
            color: var(--text-main, #ffffff);
        }
    `;

    document.head.appendChild(style);
    stylesInjected = true;
}

/* ----------------------------------------------------
   SPARKLINE (Dynamische Kurven-Farben)
---------------------------------------------------- */

function drawSparkline(canvas, values, color) {

    if (!values || values.length < 2) return;

    const ctx = canvas.getContext("2d");
    const width = canvas.offsetWidth;
    const height = canvas.offsetHeight;
    const dpr = window.devicePixelRatio || 1;

    canvas.width = width * dpr;
    canvas.height = height * dpr;
    ctx.scale(dpr, dpr);
    ctx.clearRect(0, 0, width, height);

    // Downsampling
    const maxPoints = Math.floor(width / 3);
    let sampled = values;

    if (values.length > maxPoints) {
        sampled = [];
        const bucketSize = values.length / maxPoints;
        for (let i = 0; i < maxPoints; i++) {
            const start = Math.floor(i * bucketSize);
            const end = Math.floor((i + 1) * bucketSize);
            let sum = 0;
            let count = 0;
            for (let j = start; j < end; j++) {
                sum += values[j];
                count++;
            }
            sampled.push(sum / count);
        }
    }

    // Normalize
    const min = Math.min(...sampled);
    const max = Math.max(...sampled);
    const range = max - min || 1;
    const normalized = sampled.map(v => (v - min) / range);
    const stepX = width / (normalized.length - 1);

    // Farbe: Chart-Farbe als Parameter verwenden, Fallback auf alte Logik
    const isDark = document.documentElement.getAttribute("data-theme") === "dark";
    const lineColor = color || (isDark ? "hsla(28, 100%, 58%, 1)" : "#2b6cb0");
    const shadowColor = color || (isDark ? "hsla(28, 100%, 60%, 1)" : "#4299e1");

    // Gradient aus der übergebenen Farbe ableiten
    const gradientStart = color
        ? color.replace(/,\s*[\d.]+\)$/, ", 0.28)")
        : (isDark ? "rgba(255, 119, 0, 0.28)" : "rgba(66, 153, 225, 0.25)");

    // AREA GRADIENT
    const gradient = ctx.createLinearGradient(0, 0, 0, height);
    gradient.addColorStop(0, gradientStart);
    gradient.addColorStop(1, "rgba(0, 0, 0, 0)");

    ctx.beginPath();
    normalized.forEach((v, i) => {
        const x = i * stepX;
        const y = height - (v * (height - 10)) - 5;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
    });

    ctx.lineTo(width, height);
    ctx.lineTo(0, height);
    ctx.closePath();
    ctx.fillStyle = gradient;
    ctx.fill();

    // LINE
    ctx.beginPath();
    normalized.forEach((v, i) => {
        const x = i * stepX;
        const y = height - (v * (height - 10)) - 5;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
    });

    ctx.lineWidth = 1.6;
    ctx.strokeStyle = lineColor;
    ctx.shadowColor = shadowColor;
    ctx.shadowBlur = isDark ? 10 : 2;
    ctx.lineJoin = "round";
    ctx.lineCap = "round";
    ctx.stroke();

    // Reset für nachfolgende Renderings
    ctx.shadowBlur = 0;
}

/* ----------------------------------------------------
   RENDER
---------------------------------------------------- */

export function renderCards(data) {

    injectStyles();

    const container = document.getElementById("cards");
    if (!container) return;

    container.innerHTML = "";

    const stats = data.stats || {};
    const series = data.series || {};
    const items = data.items || [];

    const isDark = document.documentElement.getAttribute("data-theme") === "dark";

    // Farben analog zum Chart generieren (gleiche HSL-Hue-Rotation)
    const seriesKeys = Object.keys(series);
    const totalKeys = Math.max(1, seriesKeys.length);

    items.forEach((item, itemIndex) => {
        const isSelfNode = item.level == 4;

        const s = stats[item.id] || { current: 0, delta: 0, min: 0, max: 0, avg: 0 };
        const values = Array.isArray(series[item.id]) ? series[item.id] : [];

        // Chart-Farbe für diese Karte berechnen (gleiche Formel wie in chart.js)
        const keyIndex = seriesKeys.indexOf(item.id);
        const colorIndex = keyIndex >= 0 ? keyIndex : itemIndex;
        const baseHue = (colorIndex * (360 / totalKeys)) % 360;
        const chartColor = isDark
            ? `hsla(${baseHue}, 100%, 65%, 1)`
            : `hsla(${baseHue}, 90%, 55%, 1)`;
        const chartColorMuted = isDark
            ? `hsla(${baseHue}, 80%, 55%, 0.25)`
            : `hsla(${baseHue}, 70%, 50%, 0.15)`;

        const card = document.createElement("div");

        if (isSelfNode) {
            card.className = "card no-click";
        } else {
            card.className = "card";
        }

        // Anhebung des Kachel-Hintergrunds im Deep-Midnight, damit sie nicht absaufen
        if (isDark) {
            card.style.background = "rgba(30, 41, 59, 0.22)";
        }

        // Farbige Oberkante als Akzent (Chart-Farbe)
        card.style.borderTop = `3px solid ${chartColor}`;

        card.setAttribute("data-active", s.current > 0 ? "true" : "false");
        const positive = s.delta >= 0;

        card.innerHTML = `
            <div class="card-header">
                <div>
                    <div class="card-title">${item.name}</div>
                    <div class="card-value">
                        ${(item.value ?? 0).toFixed(1)}
                        <span class="card-unit">kWh</span>
                    </div>
                </div>
                <div class="card-delta" style="color: ${positive ? "#00FFC2" : "#FF7A7A"};">
                    ${positive ? "+" : ""}${(item.delta ?? 0).toFixed(1)}%
                </div>
            </div>

            <div class="sparkline-wrapper">
                <canvas class="sparkline"></canvas>
            </div>

            <div class="card-stats">
                <div class="stat">
                    <div class="stat-label">Min</div>
                    <div class="stat-value">${(s.min ?? 0).toFixed(1)}</div>
                </div>
                <div class="stat">
                    <div class="stat-label">Max</div>
                    <div class="stat-value">${(s.max ?? 0).toFixed(1)}</div>
                </div>
                <div class="stat">
                    <div class="stat-label">Schnitt</div>
                    <div class="stat-value">${(s.avg ?? 0).toFixed(1)}</div>
                </div>
            </div>
        `;

        if (!isSelfNode) {
            card.addEventListener("click", () => {
                drillDown(item.id, item.name);
            });
        }

        container.appendChild(card);

        const canvas = card.querySelector(".sparkline");
        if (canvas && values.length > 0) {
            drawSparkline(canvas, values, chartColor);
        }
    });
}
